<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Domain;

/**
 * An asset (e.g. a stylesheet) that was associated with the rendered document.
 *
 * When the output format is TemplateOutputFormat::HTML_EMBEDDED the rendering engine
 * inlines text assets (CSS) directly into the HTML and marks them as embedded = true.
 * For other formats the asset is returned as-is so callers can link it externally.
 */
class RenderedAsset
{
    public function __construct(
        private readonly string $code,
        private readonly string $contentType,
        private readonly string $content,
        private readonly bool $embedded = false,
    ) {
    }

    /** Logical identifier for this asset, e.g. "theme-css". */
    public function code(): string
    {
        return $this->code;
    }

    /** MIME type of the asset content, e.g. "text/css". */
    public function contentType(): string
    {
        return $this->contentType;
    }

    /** Raw text content of the asset (for text-based assets such as CSS). */
    public function content(): string
    {
        return $this->content;
    }

    /**
     * True when this asset has already been inlined into the rendered HTML
     * (e.g. as a <style> block). Callers can skip external linking for embedded assets.
     */
    public function isEmbedded(): bool
    {
        return $this->embedded;
    }

    public function withEmbedded(bool $embedded): self
    {
        return new self($this->code, $this->contentType, $this->content, $embedded);
    }
}
